def verify(witness):
    def fail(msg):
        raise ValueError(msg)

    if not isinstance(witness, dict):
        fail('witness must be a dict')
    N = witness.get('N')
    prog = witness.get('progression')
    a = witness.get('first_term')
    d = witness.get('common_difference')
    k = witness.get('length_k')

    if not isinstance(N, int) or isinstance(N, bool) or N <= 0:
        fail('bad N')
    if not isinstance(prog, list) or not all(isinstance(p, int) and not isinstance(p, bool) for p in prog):
        fail('bad progression')
    if not isinstance(a, int) or isinstance(a, bool):
        fail('bad first_term')
    if not isinstance(d, int) or isinstance(d, bool) or d <= 0:
        fail('bad common_difference')
    if not isinstance(k, int) or isinstance(k, bool) or k <= 0:
        fail('bad length_k')
    if len(prog) != k:
        fail('length mismatch')

    def is_prime(n):
        if n < 2:
            return False
        if n < 4:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    for i in range(k):
        p = prog[i]
        if p != a + i * d:            # AP property, exact integers
            fail('not an arithmetic progression at index %d' % i)
        if not is_prime(p):           # primality, exact trial division
            fail('composite or non-prime term at index %d' % i)
        if not (1 <= p <= N):         # range condition {1,...,N}
            fail('term out of range at index %d' % i)
    return True

# invocation with the embedded witness; verify raises on any failed check
verify({
    'N': 30,
    'progression': [5, 11, 17, 23, 29],
    'first_term': 5,
    'common_difference': 6,
    'length_k': 5,
})
